// Embedded SPIR-V (generated by vr_embed_shaders onto a PRIVATE include path).
#include "inter_apply_comp.spv.hpp"
#include "inter_diff_comp.spv.hpp"
#include "survivor_ranks_comp.spv.hpp"

namespace volumetric_kit::recon::codec::detail {
namespace {

// Mirrors `Push` in inter_apply.comp.
struct ApplyPush {
  std::uint32_t item_base = 0;
  std::uint32_t num_blocks = 0;
  std::uint32_t coefficient_count = 0;
  std::uint32_t reference_count = 0;
  std::uint32_t payload_count = 0;
};
static_assert(sizeof(ApplyPush) == 20, "ApplyPush must be 20 bytes");

// Mirrors `Push` in inter_diff.comp.
struct DiffPush {
  std::uint32_t item_base = 0;
  std::uint32_t reference_count = 0;
  std::uint32_t target_count = 0;
  std::uint32_t coefficient_count = 0;
  std::uint32_t pass = 0;
};
static_assert(sizeof(DiffPush) == 20, "DiffPush must be 20 bytes");

constexpr std::uint32_t kApplyBindings = 8;
constexpr std::uint32_t kDiffBindings = 11;
constexpr std::uint32_t kRanksBindings = 3;
// inter_diff.comp's workgroup width.
constexpr std::uint32_t kDiffLanes = 64;
constexpr VkDeviceSize kEntryBytes = sizeof(volume::BlockIndex);
constexpr VkDeviceSize kWordBytes = sizeof(std::uint32_t);
constexpr VkDeviceSize kMaskBytes = kMaskWordsPerBlock * sizeof(std::uint32_t);
static_assert(kMaskWordsPerBlock == 16, "inter_apply.comp's kMaskWords is 16");
// survivor_ranks.comp's verdict and survivor count.
constexpr VkDeviceSize kSurvivorBytes = 2 * kWordBytes;

// Bytes of one entry's coefficients, as the transform reads them.
VkDeviceSize coefficient_bytes(std::uint32_t k) {
  return VkDeviceSize(coefficient_words(k)) * sizeof(std::uint32_t);
}

// A binding's range of @p entries of @p bytes each, never less than one: a
// side the frame lacks still binds a valid range, which the kernel never
// reads. Every buffer is made at least that large at create.
VkDeviceSize range(std::uint64_t entries, VkDeviceSize bytes) {
  return std::max<VkDeviceSize>(entries, 1) * bytes;
}

core::Status fail(const char* op, const std::string& why) {
  return core::Status::invalid_argument(std::string("ReferenceStore::") + op +
                                        ": " + why);
}

}  // namespace

core::Result<std::unique_ptr<ReferenceStore>> ReferenceStore::create(
    core::Device& device, core::Allocator& allocator) {
  VKC_TRY(check_device_requirements(device, "ReferenceStore::create"));
  std::unique_ptr<ReferenceStore> owned(new ReferenceStore());
  ReferenceStore& s = *owned;
  s.device_ = &device;
  s.allocator_ = &allocator;
  VkPushConstantRange push{};
  push.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
  push.size = sizeof(ApplyPush);
  VkPushConstantRange diff_push = push;
  diff_push.size = sizeof(DiffPush);
  VkPushConstantRange ranks_push = push;
  ranks_push.size = sizeof(RansPush);
  core::KernelSetBuilder kb(device);
  VKC_TRY(kb.add(s.apply_kernel_, "codec_inter_apply", vr_inter_apply_comp_spv,
                 vr_inter_apply_comp_spv_size, kApplyBindings, &push));
  VKC_TRY(kb.add(s.diff_kernel_, "codec_inter_diff", vr_inter_diff_comp_spv,
                 vr_inter_diff_comp_spv_size, kDiffBindings, &diff_push));
  VKC_TRY(kb.add(s.ranks_kernel_, "codec_survivor_ranks",
                 vr_survivor_ranks_comp_spv, vr_survivor_ranks_comp_spv_size,
                 kRanksBindings, &ranks_push));
  VKC_ASSIGN(s.pool_, kb.build());
  VkPhysicalDeviceProperties props{};
  vkGetPhysicalDeviceProperties(device.physical_device(), &props);
  s.max_workgroup_count_x_ = props.limits.maxComputeWorkGroupCount[0];
  s.max_storage_buffer_range_ = props.limits.maxStorageBufferRange;
  // One entry of each, so a side with none -- the reference of an intra
  // frame, a frame with no new blocks -- binds a buffer; and the counts.
  struct First {
    core::Buffer& buffer;
    VkDeviceSize bytes;
    const char* name;
  };
  const VkDeviceSize widest = coefficient_bytes(kVoxelsPerBlock);
  const First first[] = {
      {s.slots_[0].masks, kMaskBytes, "codec.reference_masks"},
      {s.slots_[0].coefficients, widest, "codec.reference_coefficients"},
      {s.slots_[0].list, sizeof(volume::BlockIndex), "codec.reference_list"},
      {s.slots_[1].masks, kMaskBytes, "codec.reference_masks"},
      {s.slots_[1].coefficients, widest, "codec.reference_coefficients"},
      {s.slots_[1].list, sizeof(volume::BlockIndex), "codec.reference_list"},
      {s.sources_, sizeof(ApplySource), "codec.apply_sources"},
      {s.faults_, kWordBytes, "codec.apply_faults"},
      {s.diff_masks_, kMaskBytes, "codec.diff_masks"},
      {s.diff_coefficients_, widest, "codec.diff_coefficients"},
      {s.modes_, kWordBytes, "codec.diff_modes"},
      {s.ranks_, kWordBytes, "codec.diff_ranks"},
      {s.added_, kEntryBytes, "codec.diff_added"},
      {s.survivors_, kSurvivorBytes, "codec.diff_survivors"},
  };
  for (const First& f : first) {
    VKC_TRY(core::ensure_device_scratch(device, allocator, f.buffer, f.bytes,
                                        s.max_storage_buffer_range_, f.name));
  }
  return owned;
}

core::Status ReferenceStore::reserve(std::uint32_t n, std::uint32_t k) {
  Slot& spare = slots_[current_ ^ 1u];
  struct Scratch {
    core::Buffer& buffer;
    VkDeviceSize bytes;
    const char* name;
  };
  const Scratch scratch[] = {
      {spare.masks, VkDeviceSize(n) * kMaskBytes, "codec.reference_masks"},
      {spare.coefficients, VkDeviceSize(n) * coefficient_bytes(k),
       "codec.reference_coefficients"},
      {spare.list, VkDeviceSize(n) * sizeof(volume::BlockIndex),
       "codec.reference_list"},
      {sources_, VkDeviceSize(n) * sizeof(ApplySource), "codec.apply_sources"},
  };
  // Every range first, so a frame the device cannot hold grows nothing.
  for (const Scratch& b : scratch) {
    VKC_TRY(core::check_storage_buffer_range(b.name, b.bytes,
                                             max_storage_buffer_range_));
  }
  for (const Scratch& b : scratch) {
    VKC_TRY(core::ensure_device_scratch(*device_, *allocator_, b.buffer,
                                        b.bytes, max_storage_buffer_range_,
                                        b.name));
  }
  return {};
}

core::Result<ResidentBlocks> ReferenceStore::record_apply(
    core::CommandBatch& batch, const ResidentBlocks& payload, std::uint32_t n,
    core::GpuStageScope* stage) {
  faults_host_ = 0;
  const std::uint32_t k = payload.coefficient_count;
  const Slot& reference = slots_[current_];
  const Slot& spare = slots_[current_ ^ 1u];
  const VkDeviceSize blocks = n;
  if (blocks * kMaskBytes > spare.masks.size() ||
      blocks * coefficient_bytes(k) > spare.coefficients.size() ||
      blocks * sizeof(volume::BlockIndex) > spare.list.size() ||
      blocks * sizeof(ApplySource) > sources_.size()) {
    return fail("record_apply",
                std::to_string(n) + " blocks, more than were reserved");
  }
  if (n != 0 && (payload.masks == nullptr || payload.coefficients == nullptr)) {
    return fail("record_apply", "no payload buffers");
  }
  // A P-frame's entries read the reference, which is laid out at its own K;
  // an intra frame's read none, whatever is held.
  const std::uint32_t m = payload.reference_count;
  const std::uint32_t held_m = held_ ? reference_.header.block_count : 0;
  const std::uint32_t held_k =
      held_ ? reference_.header.params.coefficient_count : 1;
  if (m != 0 && (m != held_m || k != held_k)) {
    return fail("record_apply", "a P-frame of " + std::to_string(m) +
                                    " reference entries at K " +
                                    std::to_string(k) + ", on a reference of " +
                                    std::to_string(held_m) + " at K " +
                                    std::to_string(held_k));
  }
  ResidentBlocks out;
  out.list = &spare.list;
  out.masks = &spare.masks;
  out.coefficients = &spare.coefficients;
  out.count = n;
  out.coefficient_count = k;
  if (n == 0) return out;

  const VkDeviceSize row_bytes = coefficient_bytes(k);
  core::ComputeKernel& apply = apply_kernel_;
  apply.set.write_storage_buffer(0, sources_.handle(), 0,
                                 blocks * sizeof(ApplySource));
  apply.set.write_storage_buffer(1, reference.masks.handle(), 0,
                                 range(m, kMaskBytes));
  apply.set.write_storage_buffer(2, reference.coefficients.handle(), 0,
                                 range(m, coefficient_bytes(held_k)));
  apply.set.write_storage_buffer(3, payload.masks->handle(), 0,
                                 range(payload.count, kMaskBytes));
  apply.set.write_storage_buffer(4, payload.coefficients->handle(), 0,
                                 range(payload.count, row_bytes));
  apply.set.write_storage_buffer(5, spare.masks.handle(), 0,
                                 blocks * kMaskBytes);
  apply.set.write_storage_buffer(6, spare.coefficients.handle(), 0,
                                 blocks * row_bytes);
  apply.set.write_storage_buffer(7, faults_.handle(), 0, sizeof(std::uint32_t));
  ApplyPush push;
  push.num_blocks = n;
  push.coefficient_count = k;
  push.reference_count = m;
  push.payload_count = payload.count;
  VKC_TRY(batch.fill(faults_, 0, sizeof(std::uint32_t), 0u));
  VKC_TRY(
      dispatch_items(batch, apply, push, n, 1, max_workgroup_count_x_, stage));
  VKC_TRY(batch.readback(faults_, 0, sizeof(std::uint32_t), &faults_host_));
  return out;
}

core::Status ReferenceStore::check_apply() const {
  if (faults_host_ != 0) {
    return fail("record_apply",
                std::to_string(faults_host_) +
                    " of the frame's blocks read past the reference or the "
                    "payload");
  }
  return {};
}

core::Result<ResidentBlocks> ReferenceStore::record_diff(
    core::CommandBatch& batch, std::uint32_t n, std::uint32_t k,
    core::GpuStageScope* stage) {
  if (!held_) return fail("record_diff", "no reference is held");
  const std::uint32_t held_k = reference_.header.params.coefficient_count;
  if (k != held_k) {
    return fail("record_diff", "a frame at K " + std::to_string(k) +
                                   " on a reference at K " +
                                   std::to_string(held_k));
  }
  const std::uint32_t m = reference_.header.block_count;
  const Slot& reference = slots_[current_];
  const Slot& spare = slots_[current_ ^ 1u];
  const VkDeviceSize row_bytes = coefficient_bytes(k);
  if (VkDeviceSize(n) * kMaskBytes > spare.masks.size() ||
      VkDeviceSize(n) * row_bytes > spare.coefficients.size() ||
      VkDeviceSize(n) * kEntryBytes > spare.list.size()) {
    return fail("record_diff",
                std::to_string(n) + " blocks, more than were reserved");
  }
  // The stream positions: the M reference entries, then at most n new
  // blocks.
  const std::uint64_t entries = std::uint64_t(m) + n;
  if (entries > std::numeric_limits<std::uint32_t>::max()) {
    return fail("record_diff", "more than 2^32 - 1 entries");
  }
  struct Scratch {
    core::Buffer& buffer;
    VkDeviceSize bytes;
    const char* name;
  };
  const Scratch scratch[] = {
      {diff_masks_, range(entries, kMaskBytes), "codec.diff_masks"},
      {diff_coefficients_, range(entries, row_bytes),
       "codec.diff_coefficients"},
      {modes_, range(m, kWordBytes), "codec.diff_modes"},
      {ranks_, (VkDeviceSize(m) + 1) * kWordBytes, "codec.diff_ranks"},
      {added_, range(n, kEntryBytes), "codec.diff_added"},
  };
  // Every range first, so a frame the device cannot hold grows nothing.
  for (const Scratch& b : scratch) {
    VKC_TRY(core::check_storage_buffer_range(b.name, b.bytes,
                                             max_storage_buffer_range_));
  }
  for (const Scratch& b : scratch) {
    VKC_TRY(core::ensure_device_scratch(*device_, *allocator_, b.buffer,
                                        b.bytes, max_storage_buffer_range_,
                                        b.name));
  }
  const VkDeviceSize rank_bytes = (VkDeviceSize(m) + 1) * kWordBytes;
  const core::DescriptorSet& diff = diff_kernel_.set;
  diff.write_storage_buffer(0, reference.list.handle(), 0,
                            range(m, kEntryBytes));
  diff.write_storage_buffer(1, spare.list.handle(), 0, range(n, kEntryBytes));
  diff.write_storage_buffer(2, reference.masks.handle(), 0,
                            range(m, kMaskBytes));
  diff.write_storage_buffer(3, reference.coefficients.handle(), 0,
                            range(m, row_bytes));
  diff.write_storage_buffer(4, spare.masks.handle(), 0, range(n, kMaskBytes));
  diff.write_storage_buffer(5, spare.coefficients.handle(), 0,
                            range(n, row_bytes));
  diff.write_storage_buffer(6, diff_masks_.handle(), 0,
                            range(entries, kMaskBytes));
  diff.write_storage_buffer(7, diff_coefficients_.handle(), 0,
                            range(entries, row_bytes));
  diff.write_storage_buffer(8, modes_.handle(), 0, range(m, kWordBytes));
  diff.write_storage_buffer(9, ranks_.handle(), 0, rank_bytes);
  diff.write_storage_buffer(10, added_.handle(), 0, range(n, kEntryBytes));
  const core::DescriptorSet& ranks = ranks_kernel_.set;
  ranks.write_storage_buffer(0, modes_.handle(), 0, range(m, kWordBytes));
  ranks.write_storage_buffer(1, ranks_.handle(), 0, rank_bytes);
  ranks.write_storage_buffer(2, survivors_.handle(), 0, kSurvivorBytes);

  DiffPush push;
  push.reference_count = m;
  push.target_count = n;
  push.coefficient_count = k;
  VKC_TRY(dispatch_items(batch, diff_kernel_, push, m, kDiffLanes,
                         max_workgroup_count_x_, stage));
  RansPush ranks_push;
  ranks_push.reference_count = m;
  VKC_TRY(batch.dispatch(ranks_kernel_, &ranks_push, sizeof(ranks_push), 1,
                         max_workgroup_count_x_, stage));
  push.pass = 1;
  VKC_TRY(dispatch_items(batch, diff_kernel_, push, n, kDiffLanes,
                         max_workgroup_count_x_, stage));
  ResidentBlocks out;
  out.list = &added_;
  out.masks = &diff_masks_;
  out.coefficients = &diff_coefficients_;
  out.modes = &modes_;
  out.ranks = &ranks_;
  out.count = static_cast<std::uint32_t>(entries);
  out.coefficient_count = k;
  out.reference_count = m;
  out.bounded = true;
  return out;
}

void ReferenceStore::commit(const FrameReference& reference) {
  current_ ^= 1u;
  held_ = true;
  reference_ = reference;
}

}  // namespace volumetric_kit::recon::codec::detail
